  int n;if(sscanf(line,"%dc",&n)==1||sscanf(line,"%dd",&n)==1||sscanf(line,"%da",&n)==1){
   int pi=n-4;if(pi<0)continue;int y=pi/800,x=pi%800;printf("line=%d pixel=(%d,%d) %s",n,x,y,line);
  }else fputs(line,stdout);
 }
 return 0;
}
EOF
